<?php
declare(strict_types=1);namespace App\Application\Underwriting;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\{DocumentRequirementVersion,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class DocumentRequirementService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function create(array$d,User$actor):DocumentRequirementVersion{return DB::transaction(function()use($d,$actor){$v=(DocumentRequirementVersion::where(['line_code'=>$d['line_code'],'code'=>$d['code']])->lockForUpdate()->pluck('version')->max()??0)+1;$r=DocumentRequirementVersion::create([...$d,'version'=>$v,'status'=>'DRAFT','created_by'=>$actor->id]);$this->audit->record('document.requirement.created','document_requirement',$r->id,['version'=>$v]);return$r;});}public function approve(DocumentRequirementVersion$r,User$actor):DocumentRequirementVersion{if($r->status!=='DRAFT')throw ValidationException::withMessages(['status'=>__('wave3.requirement_not_draft')]);if($r->created_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave3.maker_checker')]);return DB::transaction(function()use($r,$actor){DocumentRequirementVersion::where(['line_code'=>$r->line_code,'code'=>$r->code,'status'=>'APPROVED'])->update(['status'=>'RETIRED']);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id]);$this->audit->record('document.requirement.approved','document_requirement',$r->id,['version'=>$r->version]);$this->outbox->record('document.requirement.approved','document_requirement',$r->id,['requirement_id'=>$r->id]);return$r->refresh();});}public function applicable(string$line,array$facts):\Illuminate\Support\Collection{return DocumentRequirementVersion::where(['line_code'=>$line,'status'=>'APPROVED'])->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->get()->filter(function($r)use($facts){foreach($r->rules['conditions']??[]as$c)if(data_get($facts,$c['fact'])!==($c['equals']??null))return false;return true;})->values();}}
